//! Goggles 2 (O3) arming and keepalive sequences.
//!
//! Generated from `poc/pi_endpoint/gold_app_seq.py` in
//! https://github.com/dr00min/o3-usb-decoder at commit 64c5801ef0201a7a6070332df42e77d208fe10b2 (MIT), which
//! records the first six seconds of DJI Fly's app-to-goggles requests from a
//! live Goggles 2 capture. Only the representation changed: sender and receiver
//! are encoded as DUML address bytes (type | index << 5). Do not edit by hand.

pub struct Step {
    /// Offset from the start of the capture, in milliseconds.
    pub at_ms: u32,
    pub set: u8,
    pub id: u8,
    pub sender: u8,
    pub receiver: u8,
    /// DUML ack type (0 = none, 2 = ack after execution).
    pub ack: u8,
    pub payload: &'static str,
}

const fn s(
    at_ms: u32,
    set: u8,
    id: u8,
    sender: u8,
    receiver: u8,
    ack: u8,
    payload: &'static str,
) -> Step {
    Step {
        at_ms,
        set,
        id,
        sender,
        receiver,
        ack,
        payload,
    }
}

